package com.capstoneclanbingo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CapstoneClanBingoPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CapstoneClanBingoPlugin.class);
		RuneLite.main(args);
	}
}

package com.capstoneclanbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CapstoneClanBingoConfig.GROUP)
public interface CapstoneClanBingoConfig extends Config
{
	String GROUP = "capstoneclanbingo";

	String TEAM_CODE_KEY = "teamCode";
	String WARNING_ACCEPTED_KEY = "thirdPartyWarningAccepted";

	@ConfigItem(
			keyName = TEAM_CODE_KEY,
			name = "Team Code",
			description = "Saved Capstone Clan Bingo team code.",
			hidden = true
	)
	default String teamCode()
	{
		return "";
	}

	@ConfigItem(
			keyName = WARNING_ACCEPTED_KEY,
			name = "Third-Party Warning Accepted",
			description = "Whether the third-party server disclosure has been accepted.",
			hidden = true
	)
	default boolean thirdPartyWarningAccepted()
	{
		return false;
	}
}

package com.capstoneclanbingo;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import javax.swing.SwingUtilities;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

public class CapstoneClanBingoApiClient
{
    /*
     * Live Cloudflare Worker.
     *
     * Do not include a trailing slash here because
     * each endpoint below begins with "/api/...".
     */
    private static final String API_BASE_URL =
            "https://capstone-bingo-api.levinsteel.workers.dev";

    private static final MediaType JSON =
            MediaType.parse(
                    "application/json; charset=utf-8"
            );

    private final OkHttpClient httpClient;
    private final Gson gson;

    public CapstoneClanBingoApiClient(
            OkHttpClient httpClient,
            Gson gson
    )
    {
        this.httpClient =
                httpClient;

        this.gson =
                gson;
    }

    public void validateTeamCode(
            String teamCode,
            TeamValidationCallback callback
    )
    {
        Request request =
                new Request.Builder()
                        .url(
                                API_BASE_URL
                                        + "/api/team/"
                                        + teamCode
                        )
                        .get()
                        .build();

        httpClient
                .newCall(request)
                .enqueue(
                        new Callback()
                        {
                            @Override
                            public void onFailure(
                                    Call call,
                                    IOException exception
                            )
                            {
                                runOnSwingThread(() ->
                                        callback.onResult(
                                                false,
                                                "Could not connect to bingo server."
                                        )
                                );
                            }

                            @Override
                            public void onResponse(
                                    Call call,
                                    Response response
                            )
                            {
                                try (Response ignored = response)
                                {
                                    if (response.isSuccessful())
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        true,
                                                        "Team found."
                                                )
                                        );

                                        return;
                                    }

                                    if (response.code() == 404)
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        false,
                                                        "Team code not found."
                                                )
                                        );

                                        return;
                                    }

                                    runOnSwingThread(() ->
                                            callback.onResult(
                                                    false,
                                                    "Server returned error "
                                                            + response.code()
                                                            + "."
                                            )
                                    );
                                }
                            }
                        }
                );
    }

    public void loadBoard(
            String teamCode,
            BoardCallback callback
    )
    {
        Request request =
                new Request.Builder()
                        .url(
                                API_BASE_URL
                                        + "/api/team/"
                                        + teamCode
                                        + "/board"
                        )
                        .get()
                        .build();

        httpClient
                .newCall(request)
                .enqueue(
                        new Callback()
                        {
                            @Override
                            public void onFailure(
                                    Call call,
                                    IOException exception
                            )
                            {
                                runOnSwingThread(() ->
                                        callback.onResult(
                                                false,
                                                null,
                                                "Could not connect to bingo server."
                                        )
                                );
                            }

                            @Override
                            public void onResponse(
                                    Call call,
                                    Response response
                            )
                            {
                                try (Response ignored = response)
                                {
                                    ResponseBody responseBody =
                                            response.body();

                                    String json =
                                            responseBody == null
                                                    ? ""
                                                    : responseBody.string();

                                    if (!response.isSuccessful())
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        false,
                                                        null,
                                                        response.code() == 404
                                                                ? "Team code not found."
                                                                : "Server returned error "
                                                                + response.code()
                                                                + "."
                                                )
                                        );

                                        return;
                                    }

                                    try
                                    {
                                        BoardResponse boardResponse =
                                                gson.fromJson(
                                                        json,
                                                        BoardResponse.class
                                                );

                                        if (
                                                boardResponse == null
                                                        || !boardResponse.success
                                                        || boardResponse.tiles == null
                                        )
                                        {
                                            runOnSwingThread(() ->
                                                    callback.onResult(
                                                            false,
                                                            null,
                                                            "Server returned an invalid board."
                                                    )
                                            );

                                            return;
                                        }

                                        normalizeBoard(
                                                boardResponse
                                        );

                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        true,
                                                        boardResponse,
                                                        "Board loaded."
                                                )
                                        );
                                    }
                                    catch (Exception exception)
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        false,
                                                        null,
                                                        "Could not read board data."
                                                )
                                        );
                                    }
                                }
                                catch (IOException exception)
                                {
                                    runOnSwingThread(() ->
                                            callback.onResult(
                                                    false,
                                                    null,
                                                    "Could not read server response."
                                            )
                                    );
                                }
                            }
                        }
                );
    }

    public void saveTile(
            String teamCode,
            TileData tile,
            TileSaveCallback callback
    )
    {
        TileUpdatePayload payload =
                new TileUpdatePayload();

        payload.status =
                tile.status;

        payload.owner =
                tile.owner;

        payload.progress =
                tile.progress;

        payload.aidRequested =
                tile.aidRequested;

        payload.helpers =
                tile.helpers == null
                        ? new ArrayList<>()
                        : new ArrayList<>(
                        tile.helpers
                );

        String json =
                gson.toJson(
                        payload
                );

        RequestBody requestBody =
                RequestBody.create(
                        JSON,
                        json
                );

        Request request =
                new Request.Builder()
                        .url(
                                API_BASE_URL
                                        + "/api/team/"
                                        + teamCode
                                        + "/tile/"
                                        + tile.tileNumber
                        )
                        .put(
                                requestBody
                        )
                        .build();

        httpClient
                .newCall(request)
                .enqueue(
                        new Callback()
                        {
                            @Override
                            public void onFailure(
                                    Call call,
                                    IOException exception
                            )
                            {
                                runOnSwingThread(() ->
                                        callback.onResult(
                                                false,
                                                null,
                                                "Could not connect to bingo server."
                                        )
                                );
                            }

                            @Override
                            public void onResponse(
                                    Call call,
                                    Response response
                            )
                            {
                                try (Response ignored = response)
                                {
                                    ResponseBody responseBody =
                                            response.body();

                                    String responseJson =
                                            responseBody == null
                                                    ? ""
                                                    : responseBody.string();

                                    if (!response.isSuccessful())
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        false,
                                                        null,
                                                        "Server returned error "
                                                                + response.code()
                                                                + "."
                                                )
                                        );

                                        return;
                                    }

                                    try
                                    {
                                        TileSaveResponse saveResponse =
                                                gson.fromJson(
                                                        responseJson,
                                                        TileSaveResponse.class
                                                );

                                        if (
                                                saveResponse == null
                                                        || !saveResponse.success
                                                        || saveResponse.tile == null
                                        )
                                        {
                                            runOnSwingThread(() ->
                                                    callback.onResult(
                                                            false,
                                                            null,
                                                            "Server returned an invalid tile."
                                                    )
                                            );

                                            return;
                                        }

                                        normalizeTile(
                                                saveResponse.tile
                                        );

                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        true,
                                                        saveResponse.tile,
                                                        "Tile saved."
                                                )
                                        );
                                    }
                                    catch (Exception exception)
                                    {
                                        runOnSwingThread(() ->
                                                callback.onResult(
                                                        false,
                                                        null,
                                                        "Could not read saved tile."
                                                )
                                        );
                                    }
                                }
                                catch (IOException exception)
                                {
                                    runOnSwingThread(() ->
                                            callback.onResult(
                                                    false,
                                                    null,
                                                    "Could not read server response."
                                            )
                                    );
                                }
                            }
                        }
                );
    }

    private void normalizeBoard(
            BoardResponse board
    )
    {
        for (
                TileData tile
                : board.tiles
        )
        {
            normalizeTile(
                    tile
            );
        }
    }

    private void normalizeTile(
            TileData tile
    )
    {
        if (tile.status == null)
        {
            tile.status =
                    "OPEN";
        }

        if (tile.helpers == null)
        {
            tile.helpers =
                    new ArrayList<>();
        }
    }

    private void runOnSwingThread(
            Runnable runnable
    )
    {
        SwingUtilities.invokeLater(
                runnable
        );
    }

    public interface TeamValidationCallback
    {
        void onResult(
                boolean success,
                String message
        );
    }

    public interface BoardCallback
    {
        void onResult(
                boolean success,
                BoardResponse board,
                String message
        );
    }

    public interface TileSaveCallback
    {
        void onResult(
                boolean success,
                TileData tile,
                String message
        );
    }

    public static class BoardResponse
    {
        public boolean success;
        public TeamData team;
        public List<TileData> tiles;
    }

    public static class TeamData
    {
        public int id;
        public String code;
        public String name;
    }

    public static class TileData
    {
        public int tileNumber;

        public String status;

        public String owner;

        public String progress;

        public boolean aidRequested;

        public List<String> helpers;

        public String updatedAt;

        public TileData copy()
        {
            TileData copy =
                    new TileData();

            copy.tileNumber =
                    tileNumber;

            copy.status =
                    status;

            copy.owner =
                    owner;

            copy.progress =
                    progress;

            copy.aidRequested =
                    aidRequested;

            copy.helpers =
                    helpers == null
                            ? new ArrayList<>()
                            : new ArrayList<>(
                            helpers
                    );

            copy.updatedAt =
                    updatedAt;

            return copy;
        }
    }

    private static class TileUpdatePayload
    {
        String status;

        String owner;

        String progress;

        boolean aidRequested;

        List<String> helpers;
    }

    private static class TileSaveResponse
    {
        boolean success;

        TileData tile;
    }
}

package com.capstoneclanbingo;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

@PluginDescriptor(
		name = "Capstone Clan Bingo"
)
public class CapstoneClanBingoPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private CapstoneClanBingoConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private CapstoneClanBingoPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		CapstoneClanBingoApiClient apiClient =
				new CapstoneClanBingoApiClient(
						okHttpClient,
						gson
				);

		CapstoneClanBingoPlayerProvider playerProvider =
				new CapstoneClanBingoPlayerProvider(
						client,
						clientThread
				);

		panel =
				new CapstoneClanBingoPanel(
						apiClient,
						playerProvider,
						config,
						configManager
				);

		BufferedImage icon =
				ImageUtil.loadImageResource(
						getClass(),
						"nav_icon.png"
				);

		navButton =
				NavigationButton.builder()
						.tooltip("Capstone Clan Bingo")
						.icon(icon)
						.priority(5)
						.panel(panel)
						.build();

		clientToolbar.addNavigation(
				navButton
		);
	}

	@Override
	protected void shutDown()
	{
		if (panel != null)
		{
			panel.closeBoard();
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(
					navButton
			);
		}

		panel = null;
		navButton = null;
	}

	@Provides
	CapstoneClanBingoConfig provideConfig(
			ConfigManager configManager
	)
	{
		return configManager.getConfig(
				CapstoneClanBingoConfig.class
		);
	}
}

package com.capstoneclanbingo;

import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;

public class CapstoneClanBingoPlayerProvider
{
    private final Client client;
    private final ClientThread clientThread;

    public CapstoneClanBingoPlayerProvider(
            Client client,
            ClientThread clientThread
    )
    {
        this.client = client;
        this.clientThread = clientThread;
    }

    public void getCurrentPlayerName(
            PlayerNameCallback callback
    )
    {
        clientThread.invokeLater(() ->
        {
            Player player =
                    client.getLocalPlayer();

            String playerName = null;

            if (player != null)
            {
                playerName =
                        player.getName();
            }

            if (playerName != null)
            {
                playerName =
                        playerName.trim();
            }

            final String result =
                    playerName;

            SwingUtilities.invokeLater(() ->
            {
                if (
                        result == null
                                || result.isEmpty()
                )
                {
                    callback.onResult(
                            false,
                            null,
                            "Log into Old School RuneScape before opening the bingo board."
                    );

                    return;
                }

                callback.onResult(
                        true,
                        result,
                        "Player found."
                );
            });
        });
    }

    public interface PlayerNameCallback
    {
        void onResult(
                boolean success,
                String playerName,
                String message
        );
    }
}

package com.capstoneclanbingo;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Window;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

public class CapstoneClanBingoPanel extends PluginPanel
{
    private final CapstoneClanBingoApiClient apiClient;
    private final CapstoneClanBingoPlayerProvider playerProvider;
    private final CapstoneClanBingoConfig config;
    private final ConfigManager configManager;

    private CapstoneClanBingoBoardWindow boardWindow;

    private final JTextField teamCodeField;

    private final JButton joinTeamButton;
    private final JButton forgetTeamButton;
    private final JButton openBoardButton;

    private final JLabel teamStatusLabel;
    private final JLabel playerStatusLabel;

    private String joinedTeamCode;
    private String currentPlayerName;

    public CapstoneClanBingoPanel(
            CapstoneClanBingoApiClient apiClient,
            CapstoneClanBingoPlayerProvider playerProvider,
            CapstoneClanBingoConfig config,
            ConfigManager configManager
    )
    {
        this.apiClient = apiClient;
        this.playerProvider = playerProvider;
        this.config = config;
        this.configManager = configManager;

        setLayout(
                new BorderLayout(
                        0,
                        12
                )
        );

        JLabel title =
                new JLabel(
                        "Capstone Clan Bingo",
                        SwingConstants.CENTER
                );

        JLabel teamCodeLabel =
                new JLabel(
                        "Team Code"
                );

        teamCodeField =
                new JTextField();

        teamCodeField.setToolTipText(
                "Enter the 6-character team code from Discord"
        );

        teamCodeField.setPreferredSize(
                new Dimension(
                        180,
                        30
                )
        );

        joinTeamButton =
                new JButton(
                        "Join Team"
                );

        forgetTeamButton =
                new JButton(
                        "Forget Team"
                );

        openBoardButton =
                new JButton(
                        "Open Bingo Board"
                );

        teamStatusLabel =
                new JLabel(
                        "",
                        SwingConstants.CENTER
                );

        playerStatusLabel =
                new JLabel(
                        "<html><center>"
                                + "Player: <b>Not detected yet</b>"
                                + "</center></html>",
                        SwingConstants.CENTER
                );

        joinTeamButton.addActionListener(e ->
                ensureThirdPartyWarningAccepted(
                        this::joinTeam
                )
        );

        teamCodeField.addActionListener(e ->
                ensureThirdPartyWarningAccepted(
                        this::joinTeam
                )
        );

        openBoardButton.addActionListener(e ->
                ensureThirdPartyWarningAccepted(
                        this::detectPlayerAndLoadBoard
                )
        );

        forgetTeamButton.addActionListener(e ->
                forgetTeam()
        );

        JPanel teamPanel =
                new JPanel(
                        new GridLayout(
                                0,
                                1,
                                0,
                                6
                        )
                );

        teamPanel.add(
                teamCodeLabel
        );

        teamPanel.add(
                teamCodeField
        );

        teamPanel.add(
                joinTeamButton
        );

        teamPanel.add(
                forgetTeamButton
        );

        teamPanel.add(
                teamStatusLabel
        );

        teamPanel.add(
                playerStatusLabel
        );

        JLabel instructions =
                new JLabel(
                        "<html><center>"
                                + "Problems?"
                                + "<br>"
                                + "Double-check team code and make sure you are logged in to RuneLite."
                                + "</center></html>",
                        SwingConstants.CENTER
                );

        JPanel boardPanel =
                new JPanel(
                        new GridLayout(
                                0,
                                1,
                                0,
                                8
                        )
                );

        boardPanel.add(
                openBoardButton
        );

        boardPanel.add(
                instructions
        );

        JPanel centerPanel =
                new JPanel(
                        new BorderLayout(
                                0,
                                16
                        )
                );

        centerPanel.add(
                teamPanel,
                BorderLayout.NORTH
        );

        centerPanel.add(
                boardPanel,
                BorderLayout.CENTER
        );

        add(
                title,
                BorderLayout.NORTH
        );

        add(
                centerPanel,
                BorderLayout.CENTER
        );

        loadSavedTeam();
    }

    private void loadSavedTeam()
    {
        String savedCode =
                config.teamCode();

        if (savedCode != null)
        {
            savedCode =
                    savedCode
                            .trim()
                            .toUpperCase();
        }

        if (
                savedCode != null
                        && savedCode.matches(
                        "[A-Z0-9]{6}"
                )
        )
        {
            joinedTeamCode =
                    savedCode;

            teamCodeField.setText(
                    savedCode
            );

            openBoardButton.setEnabled(
                    true
            );

            forgetTeamButton.setEnabled(
                    true
            );

            teamStatusLabel.setText(
                    "<html><center>"
                            + "Saved team:"
                            + "<br>"
                            + "<b>"
                            + savedCode
                            + "</b>"
                            + "</center></html>"
            );

            return;
        }

        joinedTeamCode =
                null;

        openBoardButton.setEnabled(
                false
        );

        forgetTeamButton.setEnabled(
                false
        );

        teamStatusLabel.setText(
                "<html><center>"
                        + "Enter the team code you received on Discord."
                        + "</center></html>"
        );
    }

    private void ensureThirdPartyWarningAccepted(
            Runnable action
    )
    {
        if (config.thirdPartyWarningAccepted())
        {
            action.run();
            return;
        }

        String message =
                "<html>"
                        + "<div style='width: 360px;'>"
                        + "<b>Third-Party Server Notice</b>"
                        + "<br><br>"
                        + "Capstone Clan Bingo connects to:"
                        + "<br>"
                        + "<b>capstone-bingo-api.levinsteel.workers.dev</b>"
                        + "<br><br>"
                        + "To synchronize your team board, the plugin sends:"
                        + "<br>"
                        + "• Your RuneScape display name"
                        + "<br>"
                        + "• Your bingo team code"
                        + "<br>"
                        + "• Bingo tile ownership, progress, completion, "
                        + "and aid participation"
                        + "<br><br>"
                        + "Your IP address is also transmitted as part of the "
                        + "internet connection and may be visible to Cloudflare "
                        + "and the server infrastructure."
                        + "<br><br>"
                        + "The server is <b>not controlled or verified by the "
                        + "RuneLite Developers</b>."
                        + "<br><br>"
                        + "Do you want to continue?"
                        + "</div>"
                        + "</html>";

        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        message,
                        "Capstone Clan Bingo - Server Notice",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );

        if (result != JOptionPane.YES_OPTION)
        {
            return;
        }

        configManager.setConfiguration(
                CapstoneClanBingoConfig.GROUP,
                CapstoneClanBingoConfig.WARNING_ACCEPTED_KEY,
                true
        );

        action.run();
    }

    private void joinTeam()
    {
        String code =
                teamCodeField
                        .getText()
                        .trim()
                        .toUpperCase();

        if (!code.matches("[A-Z0-9]{6}"))
        {
            restoreCurrentTeamCode();

            teamStatusLabel.setText(
                    "<html><center>"
                            + "<b>Invalid team code.</b>"
                            + "<br>"
                            + "Use exactly 6 letters or numbers."
                            + "</center></html>"
            );

            return;
        }

        setBusy(
                true
        );

        teamStatusLabel.setText(
                "<html><center>"
                        + "Checking team code..."
                        + "</center></html>"
        );

        apiClient.validateTeamCode(
                code,
                (success, message) ->
                {
                    setBusy(
                            false
                    );

                    if (!success)
                    {
                        restoreCurrentTeamCode();

                        teamStatusLabel.setText(
                                "<html><center>"
                                        + "<b>"
                                        + message
                                        + "</b>"
                                        + "</center></html>"
                        );

                        return;
                    }

                    joinedTeamCode =
                            code;

                    currentPlayerName =
                            null;

                    teamCodeField.setText(
                            joinedTeamCode
                    );

                    configManager.setConfiguration(
                            CapstoneClanBingoConfig.GROUP,
                            CapstoneClanBingoConfig.TEAM_CODE_KEY,
                            joinedTeamCode
                    );

                    closeBoard();

                    openBoardButton.setEnabled(
                            true
                    );

                    forgetTeamButton.setEnabled(
                            true
                    );

                    playerStatusLabel.setText(
                            "<html><center>"
                                    + "Player: <b>Not detected yet</b>"
                                    + "</center></html>"
                    );

                    teamStatusLabel.setText(
                            "<html><center>"
                                    + "Joined team:"
                                    + "<br>"
                                    + "<b>"
                                    + joinedTeamCode
                                    + "</b>"
                                    + "</center></html>"
                    );
                }
        );
    }

    private void restoreCurrentTeamCode()
    {
        if (joinedTeamCode != null)
        {
            teamCodeField.setText(
                    joinedTeamCode
            );

            openBoardButton.setEnabled(
                    true
            );

            forgetTeamButton.setEnabled(
                    true
            );
        }
        else
        {
            teamCodeField.setText(
                    ""
            );

            openBoardButton.setEnabled(
                    false
            );

            forgetTeamButton.setEnabled(
                    false
            );
        }
    }

    private void forgetTeam()
    {
        closeBoard();

        joinedTeamCode =
                null;

        currentPlayerName =
                null;

        configManager.unsetConfiguration(
                CapstoneClanBingoConfig.GROUP,
                CapstoneClanBingoConfig.TEAM_CODE_KEY
        );

        teamCodeField.setText(
                ""
        );

        openBoardButton.setEnabled(
                false
        );

        forgetTeamButton.setEnabled(
                false
        );

        teamStatusLabel.setText(
                "<html><center>"
                        + "Team forgotten."
                        + "<br>"
                        + "Enter a new team code to reconnect."
                        + "</center></html>"
        );

        playerStatusLabel.setText(
                "<html><center>"
                        + "Player: <b>Not detected yet</b>"
                        + "</center></html>"
        );
    }

    private void detectPlayerAndLoadBoard()
    {
        // TEMP DEV BYPASS — REMOVE BEFORE FINAL PLUGIN COMMIT
        if ("FS73DA".equalsIgnoreCase(joinedTeamCode))
        {
            currentPlayerName = "DevTester";

            playerStatusLabel.setText(
                    "<html><center>"
                            + "Player:"
                            + "<br>"
                            + "<b>DevTester</b>"
                            + "</center></html>"
            );

            loadBoard();
            return;
        }
        if (joinedTeamCode == null)
        {
            return;
        }

        setBusy(
                true
        );

        playerStatusLabel.setText(
                "<html><center>"
                        + "Detecting RuneScape character..."
                        + "</center></html>"
        );

        playerProvider.getCurrentPlayerName(
                (success, playerName, message) ->
                {
                    if (!success)
                    {
                        setBusy(
                                false
                        );

                        currentPlayerName =
                                null;

                        playerStatusLabel.setText(
                                "<html><center>"
                                        + "<b>No logged-in player detected.</b>"
                                        + "<br>"
                                        + message
                                        + "</center></html>"
                        );

                        return;
                    }

                    currentPlayerName =
                            playerName;

                    playerStatusLabel.setText(
                            "<html><center>"
                                    + "Player:"
                                    + "<br>"
                                    + "<b>"
                                    + currentPlayerName
                                    + "</b>"
                                    + "</center></html>"
                    );

                    loadBoard();
                }
        );
    }

    private void loadBoard()
    {
        if (
                joinedTeamCode == null
                        || currentPlayerName == null
        )
        {
            setBusy(
                    false
            );

            return;
        }

        String teamCode =
                joinedTeamCode;

        String playerName =
                currentPlayerName;

        teamStatusLabel.setText(
                "<html><center>"
                        + "Loading shared board..."
                        + "</center></html>"
        );

        apiClient.loadBoard(
                teamCode,
                (success, board, message) ->
                {
                    setBusy(
                            false
                    );

                    if (!success)
                    {
                        closeBoard();

                        teamStatusLabel.setText(
                                "<html><center>"
                                        + "<b>Could not load board.</b>"
                                        + "<br>"
                                        + message
                                        + "</center></html>"
                        );

                        return;
                    }

                    openBoardButton.setEnabled(
                            true
                    );

                    forgetTeamButton.setEnabled(
                            true
                    );

                    teamStatusLabel.setText(
                            "<html><center>"
                                    + "Connected to:"
                                    + "<br>"
                                    + "<b>"
                                    + teamCode
                                    + "</b>"
                                    + "</center></html>"
                    );

                    playerStatusLabel.setText(
                            "<html><center>"
                                    + "Player:"
                                    + "<br>"
                                    + "<b>"
                                    + playerName
                                    + "</b>"
                                    + "</center></html>"
                    );

                    Window runeLiteWindow =
                            SwingUtilities
                                    .getWindowAncestor(
                                            this
                                    );

                    if (
                            boardWindow != null
                                    && boardWindow.isDisplayable()
                    )
                    {
                        boardWindow.dispose();

                        boardWindow =
                                null;
                    }

                    boardWindow =
                            new CapstoneClanBingoBoardWindow(
                                    runeLiteWindow,
                                    teamCode,
                                    playerName,
                                    apiClient,
                                    board
                            );

                    boardWindow.setVisible(
                            true
                    );
                }
        );
    }

    private void setBusy(
            boolean busy
    )
    {
        joinTeamButton.setEnabled(
                !busy
        );

        teamCodeField.setEnabled(
                !busy
        );

        openBoardButton.setEnabled(
                !busy
                        && joinedTeamCode != null
        );

        forgetTeamButton.setEnabled(
                !busy
                        && joinedTeamCode != null
        );
    }

    public void closeBoard()
    {
        if (
                boardWindow != null
                        && boardWindow.isDisplayable()
        )
        {
            boardWindow.dispose();
        }

        boardWindow =
                null;
    }
}

package com.capstoneclanbingo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Window;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.image.BufferedImage;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JDialog;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.util.ImageUtil;

public class CapstoneClanBingoBoardWindow extends JDialog
{
    /*
     * The artwork is stored as six full-resolution horizontal strips so each
     * individual image stays below Plugin Hub's decoded-image size limit.
     *
     * Together they reconstruct the original 1024 x 1310 board exactly.
     */
    private static final int LOGICAL_BOARD_WIDTH = 1024;
    private static final int LOGICAL_BOARD_HEIGHT = 1310;

    private static final int[] STRIP_HEIGHTS =
            {
                    219, 219, 219, 219, 219, 215
            };

    private static final String[] STRIP_FILES =
            {
                    "board_0.png",
                    "board_1.png",
                    "board_2.png",
                    "board_3.png",
                    "board_4.png",
                    "board_5.png"
            };

    private static final int PREFERRED_WIDTH = 650;
    private static final int REFRESH_INTERVAL_MS = 60_000;

    private static final DateTimeFormatter TIME_FORMAT =
            DateTimeFormatter.ofPattern("h:mm:ss a");

    private static final int[] GRID_X =
            {
                    47, 198, 354, 511, 662, 818, 968
            };

    private static final int[] GRID_Y =
            {
                    568, 692, 808, 921, 1033, 1146, 1265
            };

    private final String teamCode;
    private final String playerName;
    private final CapstoneClanBingoApiClient apiClient;

    private final CapstoneClanBingoApiClient.TileData[] tiles =
            new CapstoneClanBingoApiClient.TileData[36];

    private final boolean[] tileBusy =
            new boolean[36];

    private BingoBoardPanel boardPanel;
    private final Timer syncTimer;

    private boolean refreshInProgress;

    private SyncState syncState =
            SyncState.SYNCED;

    private String lastSyncTime =
            formatCurrentTime();

    private enum SyncState
    {
        SYNCED,
        SYNCING,
        OFFLINE
    }

    public CapstoneClanBingoBoardWindow(
            Window owner,
            String teamCode,
            String playerName,
            CapstoneClanBingoApiClient apiClient,
            CapstoneClanBingoApiClient.BoardResponse initialBoard
    )
    {
        super(owner);

        this.teamCode = teamCode;
        this.playerName = playerName;
        this.apiClient = apiClient;

        setUndecorated(true);
        setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        setResizable(false);

        initializeEmptyTiles();
        applyBoard(initialBoard);

        BufferedImage[] boardStrips =
                new BufferedImage[STRIP_FILES.length];

        for (int i = 0; i < STRIP_FILES.length; i++)
        {
            boardStrips[i] =
                    ImageUtil.loadImageResource(
                            CapstoneClanBingoBoardWindow.class,
                            STRIP_FILES[i]
                    );
        }

        int displayWidth =
                calculateDisplayWidth(owner);

        boardPanel =
                new BingoBoardPanel(
                        boardStrips,
                        displayWidth
                );

        setContentPane(boardPanel);
        pack();
        setLocationRelativeTo(owner);

        syncTimer =
                new Timer(
                        REFRESH_INTERVAL_MS,
                        e -> refreshBoard(false)
                );

        syncTimer.setRepeats(true);
        syncTimer.start();
    }

    @Override
    public void dispose()
    {
        if (syncTimer != null)
        {
            syncTimer.stop();
        }

        super.dispose();
    }

    private void initializeEmptyTiles()
    {
        for (int i = 0; i < tiles.length; i++)
        {
            tiles[i] =
                    createOpenTile(i);
        }
    }

    public void applyBoard(
            CapstoneClanBingoApiClient.BoardResponse board
    )
    {
        if (board == null || board.tiles == null)
        {
            return;
        }

        initializeEmptyTiles();

        for (
                CapstoneClanBingoApiClient.TileData incoming
                : board.tiles
        )
        {
            if (incoming == null)
            {
                continue;
            }

            int index =
                    incoming.tileNumber - 1;

            if (index < 0 || index >= tiles.length)
            {
                continue;
            }

            tiles[index] =
                    incoming.copy();
        }

        if (boardPanel != null)
        {
            boardPanel.repaint();
        }
    }

    private void refreshBoard(
            boolean showError
    )
    {
        if (
                refreshInProgress
                        || anyTileBusy()
                        || !isDisplayable()
        )
        {
            return;
        }

        refreshInProgress = true;
        syncState = SyncState.SYNCING;

        if (boardPanel != null)
        {
            boardPanel.repaint();
        }

        apiClient.loadBoard(
                teamCode,
                (success, board, message) ->
                {
                    refreshInProgress = false;

                    if (!isDisplayable())
                    {
                        return;
                    }

                    if (!success)
                    {
                        syncState = SyncState.OFFLINE;
                        boardPanel.repaint();

                        if (showError)
                        {
                            JOptionPane.showMessageDialog(
                                    this,
                                    "Could not refresh the shared board.\n\n"
                                            + message,
                                    "Bingo Server Unavailable",
                                    JOptionPane.ERROR_MESSAGE
                            );
                        }

                        return;
                    }

                    applyBoard(board);

                    syncState = SyncState.SYNCED;
                    lastSyncTime = formatCurrentTime();

                    boardPanel.repaint();
                }
        );
    }

    private boolean anyTileBusy()
    {
        for (boolean busy : tileBusy)
        {
            if (busy)
            {
                return true;
            }
        }

        return false;
    }

    private int calculateDisplayWidth(
            Window owner
    )
    {
        int width =
                PREFERRED_WIDTH;

        if (owner == null)
        {
            return width;
        }

        int availableWidth =
                Math.max(
                        350,
                        owner.getWidth() - 80
                );

        int availableHeight =
                Math.max(
                        450,
                        owner.getHeight() - 80
                );

        int widthAllowedByHeight =
                (int) Math.floor(
                        availableHeight
                                * (
                                LOGICAL_BOARD_WIDTH
                                        / (double) LOGICAL_BOARD_HEIGHT
                        )
                );

        width =
                Math.min(
                        width,
                        availableWidth
                );

        width =
                Math.min(
                        width,
                        widthAllowedByHeight
                );

        return Math.max(
                350,
                width
        );
    }

    private class BingoBoardPanel extends JPanel
    {
        private final Image[] scaledStrips;
        private final int[] stripDisplayHeights;

        private final int displayWidth;
        private final int displayHeight;

        private final double scaleX;
        private final double scaleY;

        private final Rectangle closeButtonBounds =
                new Rectangle();

        private final Rectangle refreshButtonBounds =
                new Rectangle();

        private Point dragStartScreen;
        private Point dragStartWindow;

        BingoBoardPanel(
                BufferedImage[] boardStrips,
                int displayWidth
        )
        {
            this.displayWidth =
                    displayWidth;

            displayHeight =
                    (int) Math.round(
                            displayWidth
                                    * (
                                    LOGICAL_BOARD_HEIGHT
                                            / (double) LOGICAL_BOARD_WIDTH
                            )
                    );

            scaleX =
                    displayWidth
                            / (double) LOGICAL_BOARD_WIDTH;

            scaleY =
                    displayHeight
                            / (double) LOGICAL_BOARD_HEIGHT;

            scaledStrips =
                    new Image[boardStrips.length];

            stripDisplayHeights =
                    new int[boardStrips.length];

            /*
             * Calculate each rendered strip from the same logical scale so
             * there are no visual seams or coordinate drift.
             *
             * The final strip is assigned any rounding remainder so the six
             * pieces always total exactly displayHeight pixels.
             */
            int usedDisplayHeight = 0;

            for (int i = 0; i < boardStrips.length; i++)
            {
                int stripHeight;

                if (i == boardStrips.length - 1)
                {
                    stripHeight =
                            displayHeight
                                    - usedDisplayHeight;
                }
                else
                {
                    stripHeight =
                            (int) Math.round(
                                    STRIP_HEIGHTS[i]
                                            * scaleY
                            );
                }

                stripDisplayHeights[i] =
                        stripHeight;

                scaledStrips[i] =
                        boardStrips[i].getScaledInstance(
                                displayWidth,
                                stripHeight,
                                Image.SCALE_SMOOTH
                        );

                usedDisplayHeight +=
                        stripHeight;
            }

            setPreferredSize(
                    new Dimension(
                            displayWidth,
                            displayHeight
                    )
            );

            setOpaque(true);

            addMouseListener(
                    new MouseAdapter()
                    {
                        @Override
                        public void mousePressed(
                                MouseEvent event
                        )
                        {
                            handlePopup(event);

                            if (
                                    !SwingUtilities.isLeftMouseButton(
                                            event
                                    )
                            )
                            {
                                return;
                            }

                            if (
                                    closeButtonBounds.contains(
                                            event.getPoint()
                                    )
                            )
                            {
                                dispose();
                                return;
                            }

                            if (
                                    refreshButtonBounds.contains(
                                            event.getPoint()
                                    )
                            )
                            {
                                return;
                            }

                            int tileIndex =
                                    getTileIndex(
                                            event.getX(),
                                            event.getY()
                                    );

                            if (tileIndex == -1)
                            {
                                dragStartScreen =
                                        event.getLocationOnScreen();

                                dragStartWindow =
                                        CapstoneClanBingoBoardWindow
                                                .this
                                                .getLocation();
                            }
                        }

                        @Override
                        public void mouseReleased(
                                MouseEvent event
                        )
                        {
                            handlePopup(event);

                            dragStartScreen = null;
                            dragStartWindow = null;
                        }

                        @Override
                        public void mouseClicked(
                                MouseEvent event
                        )
                        {
                            if (
                                    !SwingUtilities.isLeftMouseButton(
                                            event
                                    )
                            )
                            {
                                return;
                            }

                            if (
                                    closeButtonBounds.contains(
                                            event.getPoint()
                                    )
                            )
                            {
                                return;
                            }

                            if (
                                    refreshButtonBounds.contains(
                                            event.getPoint()
                                    )
                            )
                            {
                                refreshBoard(true);
                                return;
                            }

                            int tileIndex =
                                    getTileIndex(
                                            event.getX(),
                                            event.getY()
                                    );

                            if (tileIndex == -1)
                            {
                                return;
                            }

                            handleLeftClick(tileIndex);
                        }
                    }
            );

            addMouseMotionListener(
                    new MouseMotionAdapter()
                    {
                        @Override
                        public void mouseDragged(
                                MouseEvent event
                        )
                        {
                            if (
                                    dragStartScreen == null
                                            || dragStartWindow == null
                            )
                            {
                                return;
                            }

                            Point currentScreen =
                                    event.getLocationOnScreen();

                            int deltaX =
                                    currentScreen.x
                                            - dragStartScreen.x;

                            int deltaY =
                                    currentScreen.y
                                            - dragStartScreen.y;

                            CapstoneClanBingoBoardWindow
                                    .this
                                    .setLocation(
                                            dragStartWindow.x
                                                    + deltaX,
                                            dragStartWindow.y
                                                    + deltaY
                                    );
                        }
                    }
            );
        }

        private void handleLeftClick(
                int tileIndex
        )
        {
            if (tileBusy[tileIndex])
            {
                return;
            }

            CapstoneClanBingoApiClient.TileData current =
                    tiles[tileIndex];

            CapstoneClanBingoApiClient.TileData proposed =
                    current.copy();

            if ("OPEN".equals(current.status))
            {
                proposed.status = "OWNED";
                proposed.owner = playerName;
                proposed.progress = null;
                proposed.aidRequested = false;
                proposed.helpers = new ArrayList<>();
            }
            else if ("OWNED".equals(current.status))
            {
                proposed.status = "COMPLETE";
                proposed.progress = null;
                proposed.aidRequested = false;
            }
            else
            {
                proposed =
                        createOpenTile(tileIndex);
            }

            saveProposedTile(
                    tileIndex,
                    proposed
            );
        }

        private void handlePopup(
                MouseEvent event
        )
        {
            if (!event.isPopupTrigger())
            {
                return;
            }

            int tileIndex =
                    getTileIndex(
                            event.getX(),
                            event.getY()
                    );

            if (tileIndex == -1)
            {
                return;
            }

            showTileMenu(
                    event,
                    tileIndex
            );
        }

        private void showTileMenu(
                MouseEvent event,
                int tileIndex
        )
        {
            if (tileBusy[tileIndex])
            {
                return;
            }

            CapstoneClanBingoApiClient.TileData current =
                    tiles[tileIndex];

            JPopupMenu menu =
                    new JPopupMenu();

            JMenuItem markOpen =
                    new JMenuItem(
                            "Mark Open"
                    );

            JMenuItem claimForMe =
                    new JMenuItem(
                            "Claim for "
                                    + playerName
                    );

            JMenuItem markComplete =
                    new JMenuItem(
                            "Mark Complete"
                    );

            JMenuItem setProgress =
                    new JMenuItem(
                            "Set Progress..."
                    );

            JMenuItem aidAction =
                    new JMenuItem(
                            current.aidRequested
                                    ? "Cancel Aid Request"
                                    : "Request Aid"
                    );

            JMenuItem joinAid =
                    new JMenuItem(
                            isHelper(
                                    current,
                                    playerName
                            )
                                    ? "Leave Aid"
                                    : "Join Aid"
                    );

            markOpen.addActionListener(e ->
                    saveProposedTile(
                            tileIndex,
                            createOpenTile(
                                    tileIndex
                            )
                    )
            );

            claimForMe.addActionListener(e ->
            {
                CapstoneClanBingoApiClient.TileData proposed =
                        current.copy();

                proposed.status = "OWNED";
                proposed.owner = playerName;
                proposed.progress = null;
                proposed.aidRequested = false;
                proposed.helpers = new ArrayList<>();

                saveProposedTile(
                        tileIndex,
                        proposed
                );
            });

            markComplete.addActionListener(e ->
            {
                CapstoneClanBingoApiClient.TileData proposed =
                        current.copy();

                if (proposed.owner == null)
                {
                    proposed.owner =
                            playerName;
                }

                proposed.status = "COMPLETE";
                proposed.progress = null;
                proposed.aidRequested = false;

                saveProposedTile(
                        tileIndex,
                        proposed
                );
            });

            setProgress.addActionListener(e ->
            {
                String input =
                        JOptionPane.showInputDialog(
                                this,
                                "Enter progress as a percentage or fraction.\n"
                                        + "Examples: 70% or 7/10",
                                current.progress == null
                                        ? ""
                                        : current.progress
                        );

                if (input == null)
                {
                    return;
                }

                String normalized =
                        normalizeProgress(input);

                if (normalized == null)
                {
                    JOptionPane.showMessageDialog(
                            this,
                            "Please enter progress like 70% or 7/10.",
                            "Invalid Progress",
                            JOptionPane.ERROR_MESSAGE
                    );

                    return;
                }

                CapstoneClanBingoApiClient.TileData proposed =
                        current.copy();

                proposed.status = "OWNED";

                if (proposed.owner == null)
                {
                    proposed.owner =
                            playerName;
                }

                proposed.progress =
                        normalized;

                saveProposedTile(
                        tileIndex,
                        proposed
                );
            });

            aidAction.addActionListener(e ->
            {
                CapstoneClanBingoApiClient.TileData proposed =
                        current.copy();

                if ("COMPLETE".equals(proposed.status))
                {
                    return;
                }

                if ("OPEN".equals(proposed.status))
                {
                    proposed.status = "OWNED";
                    proposed.owner = playerName;
                }

                if (
                        !samePlayer(
                                proposed.owner,
                                playerName
                        )
                )
                {
                    JOptionPane.showMessageDialog(
                            this,
                            "Only the owner can request or cancel aid.",
                            "Aid Request",
                            JOptionPane.INFORMATION_MESSAGE
                    );

                    return;
                }

                proposed.aidRequested =
                        !proposed.aidRequested;

                saveProposedTile(
                        tileIndex,
                        proposed
                );
            });

            joinAid.addActionListener(e ->
            {
                if (
                        samePlayer(
                                current.owner,
                                playerName
                        )
                )
                {
                    JOptionPane.showMessageDialog(
                            this,
                            "You are already the owner of this tile.",
                            "Join Aid",
                            JOptionPane.INFORMATION_MESSAGE
                    );

                    return;
                }

                CapstoneClanBingoApiClient.TileData proposed =
                        current.copy();

                if (
                        isHelper(
                                proposed,
                                playerName
                        )
                )
                {
                    removeHelper(
                            proposed,
                            playerName
                    );
                }
                else
                {
                    if (!proposed.aidRequested)
                    {
                        JOptionPane.showMessageDialog(
                                this,
                                "The owner is not currently requesting aid.",
                                "Join Aid",
                                JOptionPane.INFORMATION_MESSAGE
                        );

                        return;
                    }

                    proposed.helpers.add(
                            playerName
                    );
                }

                saveProposedTile(
                        tileIndex,
                        proposed
                );
            });

            menu.add(markOpen);
            menu.add(claimForMe);
            menu.add(markComplete);

            menu.addSeparator();

            menu.add(setProgress);

            menu.addSeparator();

            if (!"COMPLETE".equals(current.status))
            {
                menu.add(aidAction);
            }

            if (
                    current.aidRequested
                            || isHelper(
                            current,
                            playerName
                    )
            )
            {
                menu.add(joinAid);
            }

            menu.show(
                    this,
                    event.getX(),
                    event.getY()
            );
        }

        private void saveProposedTile(
                int tileIndex,
                CapstoneClanBingoApiClient.TileData proposed
        )
        {
            if (tileBusy[tileIndex])
            {
                return;
            }

            tileBusy[tileIndex] = true;
            syncState = SyncState.SYNCING;

            repaint();

            apiClient.saveTile(
                    teamCode,
                    proposed,
                    (success, savedTile, message) ->
                    {
                        tileBusy[tileIndex] = false;

                        if (!success)
                        {
                            syncState = SyncState.OFFLINE;

                            repaint();

                            JOptionPane.showMessageDialog(
                                    this,
                                    "Your change was NOT saved.\n\n"
                                            + message,
                                    "Bingo Server Unavailable",
                                    JOptionPane.ERROR_MESSAGE
                            );

                            return;
                        }

                        tiles[tileIndex] =
                                savedTile.copy();

                        syncState = SyncState.SYNCED;
                        lastSyncTime = formatCurrentTime();

                        repaint();
                    }
            );
        }

        private int getTileIndex(
                int mouseX,
                int mouseY
        )
        {
            int originalX =
                    (int) (
                            mouseX
                                    / scaleX
                    );

            int originalY =
                    (int) (
                            mouseY
                                    / scaleY
                    );

            int column =
                    findGridPosition(
                            originalX,
                            GRID_X
                    );

            int row =
                    findGridPosition(
                            originalY,
                            GRID_Y
                    );

            if (row == -1 || column == -1)
            {
                return -1;
            }

            return (
                    row * 6
            ) + column;
        }

        @Override
        protected void paintComponent(
                Graphics graphics
        )
        {
            super.paintComponent(graphics);

            Graphics2D g2 =
                    (Graphics2D) graphics.create();

            g2.setRenderingHint(
                    RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON
            );

            g2.setRenderingHint(
                    RenderingHints.KEY_TEXT_ANTIALIASING,
                    RenderingHints.VALUE_TEXT_ANTIALIAS_ON
            );

            /*
             * Reconstruct the board from its six full-resolution strips.
             */
            int drawY = 0;

            for (int i = 0; i < scaledStrips.length; i++)
            {
                g2.drawImage(
                        scaledStrips[i],
                        0,
                        drawY,
                        null
                );

                drawY +=
                        stripDisplayHeights[i];
            }

            for (int row = 0; row < 6; row++)
            {
                for (int column = 0; column < 6; column++)
                {
                    int tileIndex =
                            (
                                    row * 6
                            ) + column;

                    CapstoneClanBingoApiClient.TileData tile =
                            tiles[tileIndex];

                    if (
                            tile == null
                                    || "OPEN".equals(
                                    tile.status
                            )
                    )
                    {
                        continue;
                    }

                    drawTileStatus(
                            g2,
                            tile,
                            row,
                            column
                    );
                }
            }

            drawTopControls(g2);

            g2.setColor(
                    new Color(
                            20,
                            20,
                            20,
                            220
                    )
            );

            g2.setStroke(
                    new BasicStroke(2f)
            );

            g2.drawRect(
                    1,
                    1,
                    displayWidth - 3,
                    displayHeight - 3
            );

            g2.dispose();
        }

        private void drawTopControls(
                Graphics2D g2
        )
        {
            int buttonSize = 26;
            int top = 8;

            int refreshX = 8;

            refreshButtonBounds.setBounds(
                    refreshX,
                    top,
                    buttonSize,
                    buttonSize
            );

            g2.setColor(
                    new Color(
                            0,
                            0,
                            0,
                            180
                    )
            );

            g2.fillRoundRect(
                    refreshX,
                    top,
                    buttonSize,
                    buttonSize,
                    8,
                    8
            );

            g2.setColor(Color.WHITE);

            g2.setFont(
                    new Font(
                            Font.SANS_SERIF,
                            Font.BOLD,
                            17
                    )
            );

            drawCenteredText(
                    g2,
                    "↻",
                    refreshX,
                    buttonSize,
                    top + 19
            );

            String syncText;
            Color syncColor;

            switch (syncState)
            {
                case SYNCING:
                    syncText = "SYNCING";
                    syncColor =
                            new Color(
                                    210,
                                    145,
                                    30
                            );
                    break;

                case OFFLINE:
                    syncText = "OFFLINE";
                    syncColor =
                            new Color(
                                    180,
                                    55,
                                    55
                            );
                    break;

                default:
                    syncText = "SYNCED";
                    syncColor =
                            new Color(
                                    45,
                                    145,
                                    75
                            );
                    break;
            }

            g2.setFont(
                    new Font(
                            Font.SANS_SERIF,
                            Font.BOLD,
                            10
                    )
            );

            int textWidth =
                    g2.getFontMetrics()
                            .stringWidth(syncText);

            int badgeWidth =
                    textWidth + 18;

            int badgeX =
                    refreshX
                            + buttonSize
                            + 6;

            g2.setColor(
                    new Color(
                            syncColor.getRed(),
                            syncColor.getGreen(),
                            syncColor.getBlue(),
                            225
                    )
            );

            g2.fillRoundRect(
                    badgeX,
                    top,
                    badgeWidth,
                    buttonSize,
                    8,
                    8
            );

            g2.setColor(Color.WHITE);

            drawCenteredText(
                    g2,
                    syncText,
                    badgeX,
                    badgeWidth,
                    top + 17
            );

            if (syncState == SyncState.SYNCED)
            {
                g2.setFont(
                        new Font(
                                Font.SANS_SERIF,
                                Font.PLAIN,
                                8
                        )
                );

                g2.setColor(
                        new Color(
                                255,
                                255,
                                255,
                                220
                        )
                );

                g2.drawString(
                        lastSyncTime,
                        badgeX
                                + badgeWidth
                                + 6,
                        top + 17
                );
            }

            int closeX =
                    displayWidth
                            - buttonSize
                            - 8;

            closeButtonBounds.setBounds(
                    closeX,
                    top,
                    buttonSize,
                    buttonSize
            );

            g2.setColor(
                    new Color(
                            0,
                            0,
                            0,
                            180
                    )
            );

            g2.fillRoundRect(
                    closeX,
                    top,
                    buttonSize,
                    buttonSize,
                    8,
                    8
            );

            g2.setColor(Color.WHITE);

            g2.setFont(
                    new Font(
                            Font.SANS_SERIF,
                            Font.BOLD,
                            18
                    )
            );

            drawCenteredText(
                    g2,
                    "×",
                    closeX,
                    buttonSize,
                    top + 19
            );
        }

        private void drawTileStatus(
                Graphics2D g2,
                CapstoneClanBingoApiClient.TileData tile,
                int row,
                int column
        )
        {
            int x1 =
                    (int) Math.round(
                            GRID_X[column]
                                    * scaleX
                    );

            int x2 =
                    (int) Math.round(
                            GRID_X[column + 1]
                                    * scaleX
                    );

            int y1 =
                    (int) Math.round(
                            GRID_Y[row]
                                    * scaleY
                    );

            int y2 =
                    (int) Math.round(
                            GRID_Y[row + 1]
                                    * scaleY
                    );

            int width =
                    x2 - x1;

            int height =
                    y2 - y1;

            boolean complete =
                    "COMPLETE".equals(
                            tile.status
                    );

            boolean hasProgress =
                    tile.progress != null;

            boolean aidRequested =
                    tile.aidRequested;

            Color accent;

            if (complete)
            {
                accent =
                        new Color(
                                42,
                                150,
                                75
                        );
            }
            else if (aidRequested)
            {
                accent =
                        new Color(
                                145,
                                75,
                                190
                        );
            }
            else if (hasProgress)
            {
                accent =
                        new Color(
                                45,
                                115,
                                190
                        );
            }
            else
            {
                accent =
                        new Color(
                                215,
                                145,
                                25
                        );
            }

            g2.setColor(
                    new Color(
                            accent.getRed(),
                            accent.getGreen(),
                            accent.getBlue(),
                            72
                    )
            );

            g2.fillRect(
                    x1 + 1,
                    y1 + 1,
                    width - 2,
                    height - 2
            );

            g2.setColor(
                    new Color(
                            accent.getRed(),
                            accent.getGreen(),
                            accent.getBlue(),
                            230
                    )
            );

            g2.setStroke(
                    new BasicStroke(2f)
            );

            g2.drawRect(
                    x1 + 1,
                    y1 + 1,
                    width - 3,
                    height - 3
            );

            drawParticipants(
                    g2,
                    tile,
                    x1,
                    y1,
                    width,
                    height
            );

            String statusText;

            if (complete)
            {
                statusText = "COMPLETE";
            }
            else if (
                    aidRequested
                            && hasProgress
            )
            {
                statusText =
                        "AID • "
                                + tile.progress;
            }
            else if (aidRequested)
            {
                statusText =
                        "AID REQUESTED";
            }
            else if (hasProgress)
            {
                statusText =
                        tile.progress;
            }
            else
            {
                statusText =
                        "CLAIMED";
            }

            int statusHeight =
                    Math.max(
                            18,
                            height / 4
                    );

            int statusX =
                    x1 + 4;

            int statusY =
                    y2
                            - statusHeight
                            - 4;

            int statusWidth =
                    width - 8;

            g2.setColor(
                    new Color(
                            accent.getRed(),
                            accent.getGreen(),
                            accent.getBlue(),
                            235
                    )
            );

            g2.fillRoundRect(
                    statusX,
                    statusY,
                    statusWidth,
                    statusHeight,
                    8,
                    8
            );

            int statusFontSize =
                    clamp(
                            height / 6,
                            9,
                            13
                    );

            g2.setFont(
                    new Font(
                            Font.SANS_SERIF,
                            Font.BOLD,
                            statusFontSize
                    )
            );

            String fittedStatus =
                    fitText(
                            g2,
                            statusText,
                            statusWidth - 6
                    );

            drawCenteredTextWithShadow(
                    g2,
                    fittedStatus,
                    statusX,
                    statusWidth,
                    statusY
                            + statusHeight
                            - 5
            );
        }

        private void drawParticipants(
                Graphics2D g2,
                CapstoneClanBingoApiClient.TileData tile,
                int x1,
                int y1,
                int width,
                int height
        )
        {
            List<String> names =
                    new ArrayList<>();

            if (tile.owner != null)
            {
                names.add(tile.owner);
            }

            if (tile.helpers != null)
            {
                for (String helper : tile.helpers)
                {
                    names.add(
                            "+ "
                                    + helper
                    );
                }
            }

            if (names.isEmpty())
            {
                return;
            }

            int statusHeight =
                    Math.max(
                            18,
                            height / 4
                    );

            int availableHeight =
                    height
                            - statusHeight
                            - 14;

            int lineHeight = 11;

            int maxLines =
                    Math.max(
                            1,
                            Math.min(
                                    3,
                                    (
                                            availableHeight
                                                    - 6
                                    ) / lineHeight
                            )
                    );

            List<String> visibleLines =
                    new ArrayList<>();

            if (names.size() <= maxLines)
            {
                visibleLines.addAll(names);
            }
            else
            {
                for (
                        int i = 0;
                        i < maxLines - 1;
                        i++
                )
                {
                    visibleLines.add(
                            names.get(i)
                    );
                }

                int remaining =
                        names.size()
                                - (
                                maxLines
                                        - 1
                        );

                visibleLines.add(
                        "+"
                                + remaining
                                + " more"
                );
            }

            int panelHeight =
                    8
                            + (
                            visibleLines.size()
                                    * lineHeight
                    );

            panelHeight =
                    Math.min(
                            panelHeight,
                            availableHeight
                    );

            int panelX =
                    x1 + 4;

            int panelY =
                    y1 + 4;

            int panelWidth =
                    width - 8;

            g2.setColor(
                    new Color(
                            15,
                            15,
                            15,
                            210
                    )
            );

            g2.fillRoundRect(
                    panelX,
                    panelY,
                    panelWidth,
                    panelHeight,
                    8,
                    8
            );

            int fontSize =
                    clamp(
                            height / 8,
                            8,
                            11
                    );

            g2.setFont(
                    new Font(
                            Font.SANS_SERIF,
                            Font.BOLD,
                            fontSize
                    )
            );

            int baseline =
                    panelY + 12;

            for (String line : visibleLines)
            {
                String fitted =
                        fitText(
                                g2,
                                line,
                                panelWidth - 8
                        );

                drawCenteredTextWithShadow(
                        g2,
                        fitted,
                        panelX,
                        panelWidth,
                        baseline
                );

                baseline +=
                        lineHeight;
            }
        }
    }

    private CapstoneClanBingoApiClient.TileData createOpenTile(
            int tileIndex
    )
    {
        CapstoneClanBingoApiClient.TileData tile =
                new CapstoneClanBingoApiClient.TileData();

        tile.tileNumber =
                tileIndex + 1;

        tile.status = "OPEN";
        tile.owner = null;
        tile.progress = null;
        tile.aidRequested = false;
        tile.helpers = new ArrayList<>();

        return tile;
    }

    private boolean isHelper(
            CapstoneClanBingoApiClient.TileData tile,
            String player
    )
    {
        if (
                tile == null
                        || player == null
                        || tile.helpers == null
        )
        {
            return false;
        }

        for (String helper : tile.helpers)
        {
            if (
                    samePlayer(
                            helper,
                            player
                    )
            )
            {
                return true;
            }
        }

        return false;
    }

    private void removeHelper(
            CapstoneClanBingoApiClient.TileData tile,
            String player
    )
    {
        if (
                tile.helpers == null
                        || player == null
        )
        {
            return;
        }

        tile.helpers.removeIf(
                helper ->
                        samePlayer(
                                helper,
                                player
                        )
        );
    }

    private boolean samePlayer(
            String first,
            String second
    )
    {
        if (
                first == null
                        || second == null
        )
        {
            return false;
        }

        return first
                .trim()
                .equalsIgnoreCase(
                        second.trim()
                );
    }

    private String normalizeProgress(
            String input
    )
    {
        String value =
                input
                        .trim()
                        .replace(
                                " ",
                                ""
                        );

        if (value.endsWith("%"))
        {
            try
            {
                int percent =
                        Integer.parseInt(
                                value.substring(
                                        0,
                                        value.length() - 1
                                )
                        );

                if (
                        percent < 0
                                || percent > 100
                )
                {
                    return null;
                }

                return percent
                        + "%";
            }
            catch (NumberFormatException exception)
            {
                return null;
            }
        }

        if (value.contains("/"))
        {
            String[] parts =
                    value.split("/");

            if (parts.length != 2)
            {
                return null;
            }

            try
            {
                int current =
                        Integer.parseInt(
                                parts[0]
                        );

                int total =
                        Integer.parseInt(
                                parts[1]
                        );

                if (
                        current < 0
                                || total <= 0
                                || current > total
                )
                {
                    return null;
                }

                return current
                        + "/"
                        + total;
            }
            catch (NumberFormatException exception)
            {
                return null;
            }
        }

        return null;
    }

    private int findGridPosition(
            int value,
            int[] boundaries
    )
    {
        for (
                int i = 0;
                i < boundaries.length - 1;
                i++
        )
        {
            if (
                    value >= boundaries[i]
                            && value < boundaries[i + 1]
            )
            {
                return i;
            }
        }

        return -1;
    }

    private void drawCenteredText(
            Graphics2D g2,
            String text,
            int x,
            int width,
            int baselineY
    )
    {
        int textWidth =
                g2.getFontMetrics()
                        .stringWidth(text);

        int textX =
                x
                        + (
                        width - textWidth
                ) / 2;

        g2.drawString(
                text,
                textX,
                baselineY
        );
    }

    private void drawCenteredTextWithShadow(
            Graphics2D g2,
            String text,
            int x,
            int width,
            int baselineY
    )
    {
        int textWidth =
                g2.getFontMetrics()
                        .stringWidth(text);

        int textX =
                x
                        + (
                        width - textWidth
                ) / 2;

        g2.setColor(
                new Color(
                        0,
                        0,
                        0,
                        220
                )
        );

        g2.drawString(
                text,
                textX + 1,
                baselineY + 1
        );

        g2.setColor(Color.WHITE);

        g2.drawString(
                text,
                textX,
                baselineY
        );
    }

    private String fitText(
            Graphics2D g2,
            String text,
            int maxWidth
    )
    {
        if (
                g2.getFontMetrics()
                        .stringWidth(text)
                        <= maxWidth
        )
        {
            return text;
        }

        String shortened =
                text;

        while (
                shortened.length() > 1
                        && g2.getFontMetrics()
                        .stringWidth(
                                shortened
                                        + "..."
                        )
                        > maxWidth
        )
        {
            shortened =
                    shortened.substring(
                            0,
                            shortened.length() - 1
                    );
        }

        return shortened
                + "...";
    }

    private int clamp(
            int value,
            int minimum,
            int maximum
    )
    {
        return Math.max(
                minimum,
                Math.min(
                        maximum,
                        value
                )
        );
    }

    private static String formatCurrentTime()
    {
        return LocalTime
                .now()
                .format(
                        TIME_FORMAT
                );
    }
